public class BZip2CompressorInputStream_read_TriageGen0Test {

    /**
     * Helper to create a valid BZip2 stream.
     * BZip2 format requires a specific header. 
     * Using a minimal valid BZip2 stream (empty content) is complex, 
     * so we mock the InputStream behavior or use a real small byte array.
     */
    private BZip2CompressorInputStream createStream(byte[] data) throws IOException {
        return new BZip2CompressorInputStream(new ByteArrayInputStream(data));
    }

    @Test
    public void testRead_OffsLessThanZero() throws IOException {
        byte[] data = new byte[10];
        try (BZip2CompressorInputStream bis = createStream(data)) {
            assertThrows(IndexOutOfBoundsException.class, () -> {
                bis.read(data, -1, 5);
            });
        }
    }

    @Test
    public void testRead_LenLessThanZero() throws IOException {
        byte[] data = new byte[10];
        try (BZip2CompressorInputStream bis = createStream(data)) {
            assertThrows(IndexOutOfBoundsException.class, () -> {
                bis.read(data, 0, -1);
            });
        }
    }

    @Test
    public void testRead_OutOfBounds() throws IOException {
        byte[] data = new byte[10];
        try (BZip2CompressorInputStream bis = createStream(data)) {
            assertThrows(IndexOutOfBoundsException.class, () -> {
                bis.read(data, 5, 6); // 5 + 6 > 10
            });
        }
    }

    @Test
    public void testRead_StreamClosed() throws IOException {
        byte[] data = new byte[10];
        BZip2CompressorInputStream bis = createStream(data);
        bis.close();
        assertThrows(IOException.class, () -> {
            bis.read(data, 0, 5);
        });
    }

